INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My new school', 'Today is my first week at Green Hill Junior High School. Everything here is new and exciting. There is a big library next to our classroom. It has thousands of books, and it is always quiet. There are two playgrounds, too. One is for basketball, and the other is for football. The playgrounds are large and green. My classroom is on the second floor. There are forty desks in it. My desk is near the window, so I can see the tall trees outside. My new classmates are friendly, and my teacher, Ms Wu, is kind and patient. "Welcome to your new school," she says. "There are many clubs here. You can join any of them." There is a music club, an art club and a science club. I am going to join the art club. I really like my new school!', '新学期·我的新学校', 142, 0, '[{"q": "Where is the library?", "answer": "B", "options": ["On the second floor.", "Next to the writer''s classroom.", "Near the two playgrounds.", "Outside the school gate."], "explanation": "原文 \"There is a big library next to our classroom.\""}, {"q": "Which club will the writer join?", "answer": "C", "options": ["The music club.", "The science club.", "The art club.", "The football club."], "explanation": "原文 \"I am going to join the art club.\""}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The writer''s new school and first week.", "How to play basketball.", "The writer''s favourite book.", "A trip to the library."], "explanation": "全文围绕作者初到新学校、介绍校园与感受。"}, {"q": "How does the writer probably feel about the new school?", "answer": "B", "options": ["Bored and tired.", "Happy and excited.", "Angry and sad.", "Afraid and lonely."], "explanation": "\"new and exciting\"、\"I really like my new school\" 等语气可推断愉快兴奋。"}, {"q": "\"My new classmates are friendly\" means they are ____.", "answer": "A", "options": ["kind and easy to talk to", "tall and strong", "busy and tired", "quiet and shy"], "explanation": "friendly = 友好的,易相处。"}]'::jsonb, '[{"word": "patient", "cn": "有耐心的"}, {"word": "club", "cn": "社团,俱乐部"}, {"word": "floor", "cn": "楼层"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My school', 'My school is big and beautiful. There are three tall buildings and a large playground. In front of the school, there is a lovely garden with many green trees and bright flowers. My classroom is on the second floor. It is clean and full of light. There are forty desks and a big board in it. These desks are clean, and that board is new. Behind the school, there is a small football field. Every day, students play there after lunch. The library is my favourite place, because it is quiet and full of good books. I love my school. It is like a second home to me.', '我的学校(一般现在时)', 108, 1, '[{"q": "Where is the writer''s classroom?", "answer": "B", "options": ["On the first floor.", "On the second floor.", "In the garden.", "Near the field."], "explanation": "''My classroom is on the second floor''。"}, {"q": "What is the writer''s favourite place?", "answer": "D", "options": ["The playground.", "The garden.", "The football field.", "The library."], "explanation": "''The library is my favourite place''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The writer''s big and beautiful school.", "How to play football.", "Why books are good.", "Where the garden is."], "explanation": "全文描述学校(现在时)。"}]'::jsonb, '[{"word": "playground", "cn": "操场"}, {"word": "board", "cn": "黑板"}, {"word": "field", "cn": "场地"}, {"word": "library", "cn": "图书馆"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My classroom', 'I like my classroom very much. It is big and bright, with four large windows. Through the windows, we can see green trees and blue sky. There are many desks and chairs inside. On the front wall, there is a black board. Next to it, there is a clean map of China. At the back, there is a small bookshelf full of story books. Beside it, there is an old clock. Our teacher keeps some green plants near the window. They make the room fresh and lovely. Every morning, we clean the classroom together. It is our second home, and we all take good care of it.', '我的教室(一般现在时)', 107, 1, '[{"q": "What is next to the black board?", "answer": "C", "options": ["A window.", "A bookshelf.", "A clean map of China.", "A plant."], "explanation": "''Next to it, there is a clean map of China''。"}, {"q": "What does the teacher keep near the window?", "answer": "D", "options": ["Books.", "Chairs.", "A map.", "Some green plants."], "explanation": "''Our teacher keeps some green plants near the window''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to draw a map.", "The writer''s bright and lovely classroom.", "Why plants are green.", "Where the school is."], "explanation": "全文描述教室(现在时)。"}]'::jsonb, '[{"word": "windows", "cn": "窗户"}, {"word": "board", "cn": "黑板"}, {"word": "map", "cn": "地图"}, {"word": "bookshelf", "cn": "书架"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My school day', 'Every day, I have a busy but happy time at school. I get up at six thirty and go to school at seven. Classes begin at eight o''clock. In the morning, we have four lessons. I like English and art best. At noon, we have lunch in the canteen. The food there is fresh and healthy. In the afternoon, we have two more lessons and a sport class. After school, I often play basketball with my friends. Then I go home and do my homework. In the evening, I read a book before bed. This is my day: simple but full. I love my school days, because they are full of fun and new things.', '我的一天(一般现在时·日常)', 116, 1, '[{"q": "When do classes begin?", "answer": "A", "options": ["At eight o''clock.", "At six thirty.", "At noon.", "At seven."], "explanation": "''Classes begin at eight o''clock''。"}, {"q": "What does the writer often do after school?", "answer": "C", "options": ["Read a book.", "Do homework.", "Play basketball with friends.", "Have lunch."], "explanation": "''After school, I often play basketball with my friends''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to cook lunch.", "The writer''s busy and happy school day.", "Why art is fun.", "Where the canteen is."], "explanation": "全文讲一天的日常(现在时)。"}]'::jsonb, '[{"word": "lessons", "cn": "课"}, {"word": "canteen", "cn": "食堂"}, {"word": "healthy", "cn": "健康的"}, {"word": "homework", "cn": "作业"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My favourite teacher', 'My favourite teacher is Ms Wang. She teaches us English. She is an English teacher, and she also runs an art club. She is young and kind, with a warm smile. Ms Wang is never angry with us. When we make a mistake, she helps us in a gentle way. Her lessons are always fun. She often plays word games with us, and she tells funny stories in English. Every student likes her. Outside class, she is like a big sister. She listens to us and gives us good ideas. Because of Ms Wang, I love English more and more. A good teacher is a great gift, and I am lucky to have her.', '我最喜欢的老师(一般现在时)', 114, 1, '[{"q": "What does Ms Wang teach?", "answer": "A", "options": ["English.", "Maths.", "Art.", "Music."], "explanation": "''She teaches us English''。"}, {"q": "What does Ms Wang do when students make a mistake?", "answer": "D", "options": ["She gets angry.", "She says nothing.", "She calls their parents.", "She helps them in a gentle way."], "explanation": "''she helps us in a gentle way''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to play word games.", "Why English is hard.", "Why the writer loves her kind English teacher.", "Where Ms Wang lives."], "explanation": "全文描写喜爱的老师(现在时)。"}]'::jsonb, '[{"word": "teaches", "cn": "教"}, {"word": "gentle", "cn": "温和的"}, {"word": "mistake", "cn": "错误"}, {"word": "lucky", "cn": "幸运的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'My first day', 'It is my first day at junior high school. I sit near the window with my new classmate, Ben. Our maths teacher, Mr Lee, comes in and smiles at us. "Good morning, everyone. Here is an easy question," he says. He writes some numbers on the board. "Who knows the answer?" Nobody puts up a hand. The room is very quiet. My heart beats fast. I think I know it, but I am not sure. Is my answer right? What if it is wrong? Ben looks at me. "You can try. It is OK to be wrong," he says. So I raise my hand. "Twelve," I say. My voice is small. "That is right! Well done," Mr Lee says. "This is your first lesson here: do not be afraid to try. In junior high, we learn from our mistakes." I smile at Ben. It really is a good first lesson.', '新学期·初中第一课', 150, 0, '[{"q": "Who helps the writer feel brave enough to answer?", "answer": "C", "options": ["Mr Lee, the maths teacher.", "A student near the door.", "Ben, the writer''s classmate.", "The writer''s mother."], "explanation": "Ben 说 \"You can try. It is OK to be wrong\",鼓励作者举手。"}, {"q": "What does Mr Lee write on the board?", "answer": "A", "options": ["Some numbers.", "A long sentence.", "The writer''s name.", "A famous saying."], "explanation": "原文 \"He writes some numbers on the board.\""}, {"q": "What is the best main idea of the passage?", "answer": "B", "options": ["Maths is a hard subject.", "Don''t be afraid to try, even if you may be wrong.", "The first day of school is boring.", "Teachers always ask easy questions."], "explanation": "Mr Lee 的话点题:\"do not be afraid to try... we learn from our mistakes.\""}, {"q": "Why does the writer''s heart beat fast before answering?", "answer": "D", "options": ["Because the room is too hot.", "Because he is late for class.", "Because he does not know the answer at all.", "Because he is nervous about answering in front of everyone."], "explanation": "作者知道答案却不确定、怕答错(\"I am not sure... What if it is wrong?\"),紧张。文中未直说,靠推断。"}, {"q": "In the passage, \"My voice is small\" means the writer speaks ____.", "answer": "A", "options": ["quietly and shyly", "loudly and clearly", "quickly and angrily", "slowly and proudly"], "explanation": "紧张、不自信的语境下 \"voice is small\" = 声音小、怯生生地说。"}]'::jsonb, '[{"word": "classmate", "cn": "同班同学"}, {"word": "beat", "cn": "(心)跳动"}, {"word": "afraid", "cn": "害怕的"}, {"word": "raise", "cn": "举起"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'My best friend', 'My best friend is Lily. We are in the same class. Lily is tall and thin, with long black hair and bright eyes. She is clever and kind. She is good at maths, and she often helps me with hard problems. Lily likes reading and drawing. Her pictures are beautiful and full of colour. Mine are just simple lines, but drawing together is fun. We have many things in common. We both love music and sport. After school, we often play basketball together. When I am sad, Lily always makes me smile. A good friend is like sunshine on a cold day. I am so happy to have a friend like her.', '我最好的朋友(一般现在时)', 112, 1, '[{"q": "What is Lily good at?", "answer": "D", "options": ["Music.", "Sport.", "Cooking.", "Maths."], "explanation": "''She is good at maths''。"}, {"q": "What do Lily and the writer often do after school?", "answer": "A", "options": ["Play basketball together.", "Draw pictures.", "Read books.", "Do homework."], "explanation": "''we often play basketball together''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to draw pictures.", "The writer''s clever and kind best friend.", "Why maths is hard.", "Where Lily lives."], "explanation": "全文描写最好的朋友(现在时)。"}]'::jsonb, '[{"word": "thin", "cn": "瘦的"}, {"word": "clever", "cn": "聪明的"}, {"word": "common", "cn": "共同点"}, {"word": "sunshine", "cn": "阳光"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'A new student', 'Today there is a new student in our class. His name is Sam. He comes from another city, so he does not know anyone here. At first, he is quiet and a little shy. He sits alone and says nothing. We want him to feel welcome. At lunch, my friends and I sit with him. We ask him about his hobbies and his old school. Soon, Sam begins to smile. ''I like football, just like you!'' he says. After school, we play a game together. Now Sam is not alone any more. A new friend brings new joy. It is easy to be kind, and kindness makes everyone happy.', '欢迎新同学(一般现在时)', 109, 1, '[{"q": "Why does Sam not know anyone at first?", "answer": "C", "options": ["He is shy by nature.", "He is too young.", "He comes from another city.", "He does not like people."], "explanation": "''He comes from another city, so he does not know anyone here''。"}, {"q": "What does Sam like, just like the others?", "answer": "A", "options": ["Football.", "Reading.", "Music.", "Drawing."], "explanation": "''I like football, just like you!''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to play football.", "Why cities are big.", "Where Sam is from.", "How the class welcomes a shy new student."], "explanation": "全文讲欢迎新同学(现在时)。"}]'::jsonb, '[{"word": "another", "cn": "另一个"}, {"word": "shy", "cn": "害羞的"}, {"word": "welcome", "cn": "受欢迎的"}, {"word": "hobbies", "cn": "爱好"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'My friends and I', 'I have three good friends: Ben, Kate and Tom. We are all different, and that is why we are such a happy group. Ben is funny. He always tells jokes and makes us laugh. Kate is quiet but very clever. She reads a lot of books and knows many things. Tom is strong and good at sport. He runs very fast in our class. I am not clever or quick, but I am a good listener. When one of us has a problem, we all help. We study together, play together and share everything. True friends are hard to find, and I am lucky to have mine.', '我和我的朋友们(一般现在时)', 107, 1, '[{"q": "What is Ben like?", "answer": "C", "options": ["Quiet.", "Strong.", "Funny.", "Shy."], "explanation": "''Ben is funny. He always tells jokes''。"}, {"q": "Who is good at sport?", "answer": "B", "options": ["Ben.", "Tom.", "Kate.", "The writer."], "explanation": "''Tom is strong and good at sport''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to tell jokes.", "Why reading is good.", "Where the friends live.", "The writer''s happy group of different friends."], "explanation": "全文讲我和朋友们各不同(现在时)。"}]'::jsonb, '[{"word": "different", "cn": "不同的"}, {"word": "jokes", "cn": "笑话"}, {"word": "clever", "cn": "聪明的"}, {"word": "listener", "cn": "倾听者"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'Making friends', 'Do you want to make more friends? It is not hard if you have a kind heart. First, always wear a smile. A smile is like a door; it opens easily. Second, be a good listener. When others talk, listen with care. Third, help people when they are in need. A small act of kindness means a lot. Also, share your things and your time. Do not laugh at other people''s mistakes. Everyone likes a friend who is honest and warm. Making friends takes a little time, but it is worth it. Good friends make life bright and happy. So be kind today, and friends will come to you.', '怎样交朋友(一般现在时)', 110, 1, '[{"q": "What is a smile like, according to the passage?", "answer": "A", "options": ["A door that opens easily.", "A book.", "A cold day.", "A hard problem."], "explanation": "''A smile is like a door; it opens easily''。"}, {"q": "What should you NOT do?", "answer": "B", "options": ["Wear a smile.", "Laugh at others'' mistakes.", "Listen with care.", "Share your things."], "explanation": "''Do not laugh at other people''s mistakes''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to open a door.", "Why smiles are nice.", "Simple ways to make more friends.", "Where friends live."], "explanation": "全文讲怎样交朋友(现在时·祈使)。"}]'::jsonb, '[{"word": "smile", "cn": "微笑"}, {"word": "listener", "cn": "倾听者"}, {"word": "honest", "cn": "诚实的"}, {"word": "worth", "cn": "值得的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'Music together', 'My name is Kevin. I love music. I play the drums in my school band. Every weekend, we practise in the music room. My friends and I like modern pop songs. My aunt loves music, too, but she likes old Chinese music. She plays the guzheng at home. Her music sounds soft and beautiful. Sometimes she teaches me a few notes. One day, our town has a small concert. I have an idea. "Aunt, let''s play together!" I say. She smiles and agrees. We practise every evening for two weeks. My drums are fast and strong. Her guzheng is slow and sweet. At first, the two sounds do not match. But we try again and again, and slowly they become one. On the concert day, everyone claps for us. Old music and new music make people happy together.', '音乐·新旧结合', 139, 0, '[{"q": "What instrument does Kevin play?", "answer": "A", "options": ["The drums.", "The guzheng.", "The guitar.", "The erhu."], "explanation": "原文 \"I play the drums in my school band.\""}, {"q": "When do Kevin and his aunt practise for the concert?", "answer": "C", "options": ["Every morning.", "Only at weekends.", "Every evening for two weeks.", "Once a month."], "explanation": "原文 \"We practise every evening for two weeks.\""}, {"q": "What is the best main idea of the passage?", "answer": "B", "options": ["Kevin''s aunt is a famous player.", "Old music and new music can come together and bring joy.", "Only drums make good music.", "A concert is held in the town every year."], "explanation": "末句点题:新旧音乐结合让人快乐。"}, {"q": "Why don''t the two sounds match at first?", "answer": "D", "options": ["Because Kevin plays too quietly.", "Because his aunt is angry.", "Because the music room is too small.", "Because the drums and the guzheng have very different styles."], "explanation": "drums 快而强、guzheng 慢而柔,风格不同,故起初不合;文中未直说,靠推断。"}, {"q": "\"Everyone claps for us\" means the people ____.", "answer": "A", "options": ["hit their hands together to show they like it", "walk away quietly", "fall asleep", "sing a new song"], "explanation": "clap = 鼓掌。"}]'::jsonb, '[{"word": "band", "cn": "乐队"}, {"word": "note", "cn": "音符"}, {"word": "match", "cn": "相配,匹配"}, {"word": "clap", "cn": "鼓掌"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'I love music', 'Music is a big part of my life. Every day, I listen to music at home. In the morning, happy songs help me wake up. In the evening, soft music helps me relax. I also play the guitar. I am not very good yet, but I practise a little every day. My brother does not play any instrument, but he listens every day. My favourite songs are about nature and friends. When I feel sad, music makes me feel calm. When I feel happy, music makes me want to dance. At school, I am in the music club. We sing and play together every week. Music is a language that everyone can understand. It brings people close, and it fills my heart with joy.', '我爱音乐(一般现在时)', 124, 1, '[{"q": "What helps the writer wake up in the morning?", "answer": "B", "options": ["Soft music.", "Happy songs.", "The guitar.", "A friend."], "explanation": "''In the morning, happy songs help me wake up''。"}, {"q": "What does the writer do in the music club?", "answer": "C", "options": ["Draw pictures.", "Read books.", "Sing and play together every week.", "Dance alone."], "explanation": "''We sing and play together every week''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How music is a big and happy part of the writer''s life.", "How to play the guitar.", "Why songs are short.", "Where the club is."], "explanation": "全文讲热爱音乐(现在时)。"}]'::jsonb, '[{"word": "relax", "cn": "放松"}, {"word": "guitar", "cn": "吉他"}, {"word": "practise", "cn": "练习"}, {"word": "language", "cn": "语言"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'Our music club', 'Our school has a wonderful music club, and I am a happy member. We meet every Friday afternoon in the music hall. Some students play the piano, and others play the guitar or the drum. A few of us just love to sing. Our teacher, Mr Li, is kind and patient. He helps everyone, even the ones who are shy. In the club, we do not need to be the best. We only need to enjoy the music. At the end of the year, we put on a big show for the whole school. Everyone claps for us. The music club is like a warm family. There we make friends and make music together.', '学校音乐社(一般现在时)', 114, 1, '[{"q": "When does the music club meet?", "answer": "D", "options": ["Every Monday morning.", "Every weekend.", "Every evening.", "Every Friday afternoon."], "explanation": "''We meet every Friday afternoon in the music hall''。"}, {"q": "What do the club members need to do?", "answer": "B", "options": ["Be the best players.", "Enjoy the music.", "Play only the piano.", "Sing alone."], "explanation": "''We only need to enjoy the music''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to play the drum.", "Why shows are long.", "Where Mr Li lives.", "A warm school music club where students make music together."], "explanation": "全文讲音乐社(现在时)。"}]'::jsonb, '[{"word": "member", "cn": "成员"}, {"word": "drum", "cn": "鼓"}, {"word": "patient", "cn": "有耐心的"}, {"word": "claps", "cn": "鼓掌"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'My family and music', 'In my family, everyone loves music in their own way. My father plays the guitar. On weekends, he sings old songs, and we all listen. My mother has a soft, sweet voice. She sings when she cooks in the kitchen. My little sister is only five, but she loves to dance to every song. As for me, I am learning the piano. Some evenings, we make music together in the living room. It is not always perfect, but it is always fun. Music fills our home with warmth and joy. When we play together, we feel close and happy. A family that shares music shares happiness too.', '我家人和音乐(一般现在时)', 107, 1, '[{"q": "What does the mother do when she cooks?", "answer": "C", "options": ["She dances.", "She plays the guitar.", "She sings.", "She reads."], "explanation": "''She sings when she cooks in the kitchen''。"}, {"q": "What is the writer learning?", "answer": "A", "options": ["The piano.", "The guitar.", "The drum.", "To dance."], "explanation": "''I am learning the piano''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to cook dinner.", "Why sisters dance.", "How music brings the writer''s family joy and warmth.", "Where the piano is."], "explanation": "全文讲家人与音乐(现在时)。"}]'::jsonb, '[{"word": "voice", "cn": "嗓音"}, {"word": "kitchen", "cn": "厨房"}, {"word": "piano", "cn": "钢琴"}, {"word": "warmth", "cn": "温暖"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'Music every day', 'Does music matter in your day? It is all around us, every single day. In the early morning, birds sing sweet songs in the trees. On the way to school, I hear music from shops and cars. In our English class, we sometimes sing songs to learn new words. It is a fun way to study. At lunch, the canteen plays soft music, and everyone feels calm. In sport class, we move and jump to happy music. Even at home, my mother turns on the radio while she cooks. Music makes hard work feel light and happy. Life without music is like a garden without flowers. I am always glad to have music in every day.', '每天的音乐(一般现在时)', 116, 1, '[{"q": "How do the students sometimes learn new words in English class?", "answer": "D", "options": ["By drawing.", "By playing games.", "By reading aloud.", "By singing songs."], "explanation": "''we sometimes sing songs to learn new words''。"}, {"q": "What does the mother turn on while she cooks?", "answer": "A", "options": ["The radio.", "The television.", "The light.", "The fan."], "explanation": "''my mother turns on the radio while she cooks''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to sing well.", "How music is a part of everyday life.", "Why birds sing.", "Where the canteen is."], "explanation": "全文讲每天的音乐(现在时)。"}]'::jsonb, '[{"word": "radio", "cn": "收音机"}, {"word": "calm", "cn": "平静的"}, {"word": "canteen", "cn": "食堂"}, {"word": "glad", "cn": "高兴的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'Grandpa''s silent love', 'My grandpa is a quiet man. He never says ''I love you''. But I can feel my grandpa''s love in many small things. Every morning, he cooks my breakfast, and my favourite egg is always on my plate. On cold days, he puts my sister''s gloves and my coat by the door. He always checks the air in my bike''s tyres before I go to school. When my mother''s hands are busy with work, Grandpa quietly takes care of the whole family''s dinner. He never asks for a ''thank you''. On my birthday, there is never a big party, but a bowl of long noodles is always ready — that is Grandpa''s quiet gift. Sometimes I see Grandpa mending my old schoolbag. His hands are slow, but his face is calm and happy, and my eyes feel wet. My grandpa''s words are few. He gives no hugs and no kisses. But his love is real, and I feel it every single day, warm and strong.', '家庭·沉默的爱', 171, 0, '[{"q": "What does Grandpa do every morning?", "answer": "A", "options": ["He cooks the writer''s breakfast.", "He mends the schoolbag.", "He drives the writer to school.", "He buys new gloves."], "explanation": "原文 \"Every morning, he cooks my breakfast.\""}, {"q": "Who takes care of the family''s dinner when mother is busy?", "answer": "C", "options": ["The writer''s mother.", "The writer''s sister.", "Grandpa.", "The writer."], "explanation": "''Grandpa quietly takes care of the whole family''s dinner.''"}, {"q": "What is the main idea of the passage?", "answer": "B", "options": ["Grandpa is a good cook.", "Grandpa shows his love through actions, not words.", "The writer''s family is very busy.", "Winter is a hard season."], "explanation": "全文用小事说明爷爷用行动而非言语表达爱。"}, {"q": "Why do the writer''s eyes feel wet?", "answer": "D", "options": ["Because the room was cold.", "Because the schoolbag was broken.", "Because Grandpa was ill.", "Because the writer was moved by Grandpa''s quiet care."], "explanation": "看到爷爷默默补书包而感动;文中未直说,靠推断。"}, {"q": "\"Grandpa mending my old schoolbag\" — \"mending\" means ____.", "answer": "A", "options": ["repairing", "washing", "buying", "throwing away"], "explanation": "mend = 修补。"}]'::jsonb, '[{"word": "mend", "cn": "修补"}, {"word": "calm", "cn": "平静的"}, {"word": "gloves", "cn": "手套"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'My grandpa', 'My grandpa is seventy years old, but he is still strong and happy. He has short white hair and a kind face. Every morning, he gets up early and does exercise in the park. He walks slowly with a cup of tea in his hand. Grandpa loves stories. In the evening, he tells me about his young days. Grandpa''s stories are always warm and funny. He also plays chess very well, and he often teaches me. In the corner of the room, my grandpa''s chess board is ready for a game. Grandpa is patient and wise. He often tells me: a kind heart matters, not money. I learn so much from him. I hope my grandpa stays healthy and happy for many years.', '我的爷爷(一般现在时·描写人)', 123, 1, '[{"q": "What does grandpa do every morning?", "answer": "C", "options": ["He tells stories.", "He plays chess.", "He does exercise in the park.", "He drinks tea in bed."], "explanation": "''Every morning, he gets up early and does exercise in the park''。"}, {"q": "What matters to grandpa?", "answer": "B", "options": ["A good story.", "A kind heart.", "A game of chess.", "A cup of tea."], "explanation": "''a kind heart matters, not money''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to play chess.", "Why tea is warm.", "Where the park is.", "The writer''s kind and wise grandpa."], "explanation": "全文描写爷爷(现在时)。"}]'::jsonb, '[{"word": "exercise", "cn": "锻炼"}, {"word": "chess", "cn": "象棋"}, {"word": "patient", "cn": "有耐心的"}, {"word": "wise", "cn": "睿智的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'Grandma''s garden', 'My grandma has a lovely garden behind her house. She takes care of it every day. In the garden, there are green vegetables and bright flowers. In spring, she plants small seeds in the soft soil. In summer, the garden is full of life. Bees fly around the flowers, and birds sing in the tree. Grandma waters the plants every morning and evening. She talks to them softly, as if they are her friends. When the vegetables grow big, she shares them with our neighbours. The neighbours'' children come to help too. Everyone loves grandma''s garden. It is a small, green world, full of care and love. I always feel calm and happy there.', '奶奶的菜园(一般现在时)', 115, 1, '[{"q": "When does grandma water the plants?", "answer": "A", "options": ["Every morning and evening.", "Only at noon.", "Once a week.", "Only in spring."], "explanation": "''Grandma waters the plants every morning and evening''。"}, {"q": "What does grandma do when the vegetables grow big?", "answer": "B", "options": ["She sells them.", "She shares them with the neighbours.", "She keeps them all.", "She throws them away."], "explanation": "''she shares them with our neighbours''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to sell vegetables.", "Why bees fly.", "Grandma''s lovely garden full of care and love.", "Where the house is."], "explanation": "全文讲奶奶的菜园(现在时)。"}]'::jsonb, '[{"word": "vegetables", "cn": "蔬菜"}, {"word": "seeds", "cn": "种子"}, {"word": "soil", "cn": "土壤"}, {"word": "neighbours", "cn": "邻居"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'My family', 'There are four people in my family: my father, my mother, my little brother and me. My father is a doctor. He is busy but very kind. He helps sick people every day. The patients'' smiles make him happy. My mother is a teacher. She loves children, and she is patient at home too. My little brother is only six. He is funny and full of energy. My brother''s favourite toy is a small red car. He always makes us laugh. As for me, I am a student in Grade Seven. I love reading and sport. On weekends, we do many things together. We cook, play games and take walks in the park. My family is not rich, but we are warm and happy. I love them with all my heart.', '我的家人(一般现在时)', 131, 1, '[{"q": "What is the writer''s father?", "answer": "A", "options": ["A doctor.", "A teacher.", "A worker.", "A driver."], "explanation": "''My father is a doctor''。"}, {"q": "What does the family do on weekends?", "answer": "D", "options": ["Stay in different rooms.", "Work alone.", "Watch television all day.", "Cook, play games and take walks together."], "explanation": "''we do many things together. We cook, play games and take walks''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The writer''s warm and happy family.", "How to be a doctor.", "Why children laugh.", "Where the park is."], "explanation": "全文介绍家人(现在时)。"}]'::jsonb, '[{"word": "doctor", "cn": "医生"}, {"word": "patient", "cn": "有耐心的"}, {"word": "energy", "cn": "精力"}, {"word": "grade", "cn": "年级"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'Sunday with my family', 'Sunday is my favourite day, because I spend it with my family. In the morning, we get up late and have a big breakfast together. My mother''s breakfast is simple, and the kitchen smells wonderful. After breakfast, my father and I wash the car. My little brother helps, but he plays with the water and forgets to work! In the afternoon, we often visit my grandparents. Grandma always has sweet fruit for us. In the evening, we watch a film at home. We sit close on the sofa and laugh together. At the end of the day, my parents'' faces are calm and happy. Sunday is not about big things. It is about being close to the people we love. I always want Sunday to go on and on.', '和家人过周日(一般现在时·日常)', 129, 1, '[{"q": "What does the writer do with his father in the morning?", "answer": "D", "options": ["Cook eggs.", "Visit grandparents.", "Watch a film.", "Wash the car."], "explanation": "''my father and I wash the car''。"}, {"q": "What does grandma always have for them?", "answer": "C", "options": ["A new film.", "A big car.", "Sweet fruit.", "A funny story."], "explanation": "''Grandma always has sweet fruit for us''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to wash a car.", "How the writer enjoys a warm Sunday with family.", "Why fruit is sweet.", "Where grandparents live."], "explanation": "全文讲家庭周日(现在时)。"}]'::jsonb, '[{"word": "breakfast", "cn": "早餐"}, {"word": "grandparents", "cn": "祖父母"}, {"word": "sofa", "cn": "沙发"}, {"word": "wish", "cn": "希望"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'Our warm Spring Festival', 'The Spring Festival is my favourite time of the year, and my family always celebrates it together. Before the festival, we always clean the house and usually put red couplets on the door. Every year, my friend Tom comes to join us. He is from Canada, and he always enjoys our festival. On New Year''s Eve, my grandma always cooks a big meal, and we always eat dumplings. ''Why dumplings?'' Tom often asks. ''Their shape is like old Chinese gold,'' my dad always says. ''They stand for good luck.'' Before the meal, we usually give red packets to the children. Tom sometimes forgets the lucky words, but my grandma always helps him. Tom never makes good dumplings, and his first one always looks funny, but he is always proud of it. Sometimes we drop the dumplings into the water too fast, and everyone laughs. At midnight, we always watch the fireworks together. A festival like this is never just about food — it is always about family, and that is why our Spring Festival is always so warm.', '节日·温暖的春节(频度副词)', 178, 0, '[{"q": "Where is Tom from?", "answer": "B", "options": ["China.", "Canada.", "America.", "Japan."], "explanation": "''He is from Canada.''"}, {"q": "What does the family always eat on New Year''s Eve?", "answer": "A", "options": ["Dumplings.", "Mooncakes.", "Fish.", "Rice."], "explanation": "''we always eat dumplings.''"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to make dumplings.", "Tom is good at Chinese.", "How the family always celebrates the Spring Festival warmly together.", "The writer''s family is very rich."], "explanation": "全文讲一家人每年温暖地一起过春节。"}, {"q": "Why is their Spring Festival so warm?", "answer": "D", "options": ["Because Tom brings many gifts.", "Because they eat a lot of food.", "Because their house is very big.", "Because they always do the customs together as a family."], "explanation": "结尾:it is always about family。"}, {"q": "In the passage, ''stand for'' means ____.", "answer": "A", "options": ["represent", "forget", "cook", "clean"], "explanation": "stand for=象征、代表。"}]'::jsonb, '[{"word": "couplets", "cn": "对联"}, {"word": "dumpling", "cn": "饺子"}, {"word": "stand for", "cn": "象征,代表"}, {"word": "fireworks", "cn": "烟花"}, {"word": "proud", "cn": "自豪的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'Spring Festival', 'Spring Festival is a big festival in China. It comes in winter, at the start of the new year. Before the festival, every family usually cleans the house from top to bottom. People put up red words and bright lanterns on the doors. Red is the colour of luck and joy. The streets are never quiet during the festival. On New Year''s Eve, the whole family sits together for a big dinner. There are many nice dishes, and fish is a must, because it means good luck. Children love this time best. They wear new clothes and get red packets with money inside. Everywhere, people smile and say kind words. Spring Festival is a warm time of family, food and hope.', '春节(一般现在时·习俗)', 122, 1, '[{"q": "What colour is the colour of luck and joy?", "answer": "D", "options": ["Blue.", "Green.", "White.", "Red."], "explanation": "''Red is the colour of luck and joy''。"}, {"q": "Why is fish a must at the dinner?", "answer": "A", "options": ["Because it means good luck.", "Because it is cheap.", "Because it is easy to cook.", "Because children like it."], "explanation": "''fish is a must, because it means good luck''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to cook fish.", "Why winter is cold.", "The customs and warmth of Spring Festival.", "Where China is."], "explanation": "全文讲春节习俗(现在时)。"}]'::jsonb, '[{"word": "festival", "cn": "节日"}, {"word": "lanterns", "cn": "灯笼"}, {"word": "luck", "cn": "运气"}, {"word": "packets", "cn": "(红)包"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'Festival food', 'At Spring Festival, food is very important. Every family cooks many special dishes. In the north of China, people love dumplings. The whole family makes them together. They put the dumplings into hot water, and soon they are ready to eat. In the south, people eat sweet rice cakes and fish. Every dish has a lucky meaning. Families sometimes try new dishes, but fish is never missing. Fish means ''more every year'', and dumplings look like old gold money. Sweet food means a sweet life. Grandma always cooks a big meal for the new year. The kitchen is warm and full of good smells. When we eat together, we feel happy and thankful. Festival food is not just tasty; it carries our best wishes.', '春节的食物(一般现在时)', 123, 1, '[{"q": "What do people in the north of China love to eat?", "answer": "B", "options": ["Rice cakes.", "Dumplings.", "Bread.", "Noodles."], "explanation": "''In the north of China, people love dumplings''。"}, {"q": "What does fish mean?", "answer": "A", "options": ["''More every year''.", "A long life.", "Good health.", "A happy home."], "explanation": "''Fish means more every year''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to make rice cakes.", "Why grandma is old.", "Where the kitchen is.", "The lucky meaning of festival food."], "explanation": "全文讲春节食物寓意(现在时)。"}]'::jsonb, '[{"word": "dumplings", "cn": "饺子"}, {"word": "cakes", "cn": "糕"}, {"word": "meaning", "cn": "含义"}, {"word": "thankful", "cn": "感恩的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'Red for luck', 'How often do you see red everywhere? At Spring Festival, you see it all around. Red is a very lucky colour in China. On the doors, there are red words with good wishes. On the windows, there are red paper cuts of flowers and animals. People often wear red clothes and red hats. Children get red packets with money inside. At night, red lanterns light up the streets. Even the sky is full of red light from the fireworks. Why do people love red so much? Red is the colour of fire and the sun. It stands for joy, warmth and good luck. During the festival, the red colour brings a happy feeling to every home. It fills the new year with hope.', '红色代表吉祥(一般现在时)', 123, 1, '[{"q": "What is on the windows during Spring Festival?", "answer": "B", "options": ["Red lanterns.", "Red paper cuts of flowers and animals.", "Red hats.", "Red money."], "explanation": "''On the windows, there are red paper cuts of flowers and animals''。"}, {"q": "What does red stand for?", "answer": "C", "options": ["Cold and snow.", "Night and sleep.", "Joy, warmth and good luck.", "Rain and wind."], "explanation": "''It stands for joy, warmth and good luck''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Why red is the lucky colour of Spring Festival.", "How to cut paper.", "Why the sun is hot.", "Where the streets are."], "explanation": "全文讲红色寓意(现在时)。"}]'::jsonb, '[{"word": "cuts", "cn": "剪纸"}, {"word": "packets", "cn": "(红)包"}, {"word": "lanterns", "cn": "灯笼"}, {"word": "fireworks", "cn": "烟花"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'Family time at Spring Festival', 'Spring Festival is a time for family. Even people who work far away come home for the festival. Trains and buses are full of happy travellers. At home, everyone helps. Grandma is usually busy in the kitchen, and she never looks tired. Father and the children clean the rooms and put up red words. On New Year''s Eve, the whole family sits around one big table. We eat, talk and laugh late into the night. The old people often tell stories, and the children play games. Outside, we can hear happy fireworks. No one wants to go to bed. For many families, this is the only time of the year when everyone is together. That is why Spring Festival is so warm and dear to us.', '春节的家人时光(一般现在时)', 127, 1, '[{"q": "Why are trains and buses full before the festival?", "answer": "B", "options": ["People go on holiday.", "People who work far away come home.", "People go shopping.", "People move house."], "explanation": "''people who work far away come home for the festival''。"}, {"q": "What do the old people do on New Year''s Eve?", "answer": "C", "options": ["Cook in the kitchen.", "Clean the rooms.", "Tell stories.", "Play fireworks."], "explanation": "''The old people often tell stories''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to cook a big dinner.", "Why buses are slow.", "Where grandma lives.", "Why Spring Festival is a warm time for family together."], "explanation": "全文讲春节家人团聚(现在时)。"}]'::jsonb, '[{"word": "travellers", "cn": "旅客"}, {"word": "fireworks", "cn": "烟花"}, {"word": "stories", "cn": "故事"}, {"word": "dear", "cn": "珍贵的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'My little seed', 'Today I put a small seed into the ground. It looks weak now, but it will become something great one day. First, it will need water and sunlight. In a few days, a tiny green leaf is going to appear. The leaf will drink the sunlight and make food for the plant. Slowly, the stem will grow tall and strong. Next spring, my little seed is going to be a young tree. Birds will come and build their nests in it. In summer, it will give us cool shade. Children will play under it on hot days. In autumn, its leaves will turn gold and fall softly to the ground. People will rest under it and tell old stories. The tree will also help the air. It is going to take in bad gas and give out fresh oxygen. Small animals will find food and a home in its branches. Years later, I will be an old man, but my tree will still be here. It will drop new seeds, and more trees are going to grow. One small seed will change a whole hill. Plants are quiet, but they are truly powerful.', '植物的力量', 193, 0, '[{"q": "What does the seed need first?", "answer": "A", "options": ["Water and sunlight.", "Birds and animals.", "Cool shade.", "Fresh oxygen."], "explanation": "原文 \"First, it will need water and sunlight.\""}, {"q": "What will the tree give people in summer?", "answer": "B", "options": ["New seeds.", "Cool shade.", "Fresh fruit.", "A bird''s nest."], "explanation": "原文 \"In summer, it will give us cool shade.\""}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["How to water a plant.", "Birds like to live in trees.", "A small seed/plant has great power over time.", "Summer is the best season."], "explanation": "全文用一粒种子的未来说明植物的力量。"}, {"q": "Why does the writer say \"one small seed will change a whole hill\"?", "answer": "D", "options": ["Because the seed is very big.", "Because people will cut the tree down.", "Because the hill is small.", "Because the tree will drop seeds and more trees will grow."], "explanation": "由树落籽、更多树生长推断;文中给出线索。"}, {"q": "In the passage, \"powerful\" means ____.", "answer": "A", "options": ["having great strength and effect", "very small and weak", "green and tall", "quiet and slow"], "explanation": "powerful = 强大的、有力量的。"}]'::jsonb, '[{"word": "seed", "cn": "种子"}, {"word": "shade", "cn": "树荫,阴凉处"}, {"word": "oxygen", "cn": "氧气"}, {"word": "branch", "cn": "树枝"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'My little seed', 'This spring, I have a little seed, and I am going to grow it. First, I will put some soft soil in a small pot. Then I am going to make a little hole and put the seed inside. I will cover it gently with soil and give it a little water. Every day, I will put the pot near the window, so it can get the warm sun. Will it grow fast? No, it will not. At first, nothing will happen, and I will feel worried. But one morning, a tiny green leaf will come out of the soil! Plants need sun, water, soil and care. This little seed is going to teach me to be patient.', '我的小种子(一般现在时)', 118, 1, '[{"q": "Where does the writer put the pot every day?", "answer": "C", "options": ["Under the bed.", "In a dark box.", "Near the window for warm sun.", "Outside in the rain."], "explanation": "''I will put the pot near the window, so it can get the warm sun''。"}, {"q": "What do plants need to grow?", "answer": "D", "options": ["Only water.", "Only sun.", "Nothing at all.", "Sun, water, soil and care."], "explanation": "''plants need sun, water, soil and care''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer plans to grow a seed and learn patience.", "How to buy a pot.", "Why windows are warm.", "Where the soil is."], "explanation": "全文讲种一粒种子(现在时)。"}]'::jsonb, '[{"word": "seed", "cn": "种子"}, {"word": "soil", "cn": "土壤"}, {"word": "pot", "cn": "花盆"}, {"word": "patient", "cn": "有耐心的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'Our school garden', 'Our school has a small but lovely garden. Every class takes care of one part of it. Next term, we are going to grow more vegetables and flowers. Every week, we water the plants and pull out the weeds. In spring, we are going to plant new seeds. In summer, the garden will be green and full of life. Bees and butterflies will come to the flowers. In autumn, we will pick the vegetables and share them with our teachers. Are you going to join us? The garden will not look after itself, but with our hands it will grow well. This little green corner will make our school a lovely place.', '我们的校园菜园(一般现在时)', 112, 1, '[{"q": "What do the students do every week in the garden?", "answer": "B", "options": ["Pick vegetables.", "Water the plants and pull out the weeds.", "Plant new trees.", "Catch butterflies."], "explanation": "''Every week, we water the plants and pull out the weeds''。"}, {"q": "What will the students do with the vegetables in autumn?", "answer": "A", "options": ["Share them with the teachers.", "Sell them.", "Keep them all.", "Throw them away."], "explanation": "''we will pick the vegetables and share them with our teachers''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to catch bees.", "The school garden and what students learn from it.", "Why summer is green.", "Where the school is."], "explanation": "全文讲校园菜园(现在时)。"}]'::jsonb, '[{"word": "vegetables", "cn": "蔬菜"}, {"word": "weeds", "cn": "杂草"}, {"word": "butterflies", "cn": "蝴蝶"}, {"word": "team", "cn": "团队"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'How plants live', 'Plants are living things, just like animals. They need four things to live: sun, water, air and soil. The sun gives them light and warmth. Water and soil give them food. Air helps them breathe. Green leaves are very important. They take in light from the sun and make food for the whole plant. Roots grow down into the soil. They hold the plant in place and drink water. Plants are very useful to us. Will our world be green in the future? It will not, if we forget them. Next month, our class is going to plant ten young trees. We will take good care of every tree and flower.', '植物如何生活(一般现在时·科普)', 111, 1, '[{"q": "What do green leaves do?", "answer": "C", "options": ["Hold the plant in place.", "Drink water from the soil.", "Take in light and make food.", "Give the plant air."], "explanation": "''They take in light from the sun and make food''。"}, {"q": "What do the roots do?", "answer": "D", "options": ["Make food.", "Take in light.", "Clean the air.", "Hold the plant in place and drink water."], "explanation": "''They hold the plant in place and drink water''。"}, {"q": "What is the passage mainly about?", "answer": "C", "options": ["How to grow fruit.", "Why leaves are green only.", "How plants live and why they are useful.", "Where roots go."], "explanation": "全文讲植物如何生活(现在时·科普)。"}]'::jsonb, '[{"word": "soil", "cn": "土壤"}, {"word": "breathe", "cn": "呼吸"}, {"word": "leaves", "cn": "叶子"}, {"word": "roots", "cn": "根"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'Green is life', 'Look around you. Green is everywhere in nature. Trees, grass and leaves are all green. Green is the colour of life. Plants make our world fresh and beautiful. On a hot day, a big tree gives us cool shade. Birds build their homes in the trees. But some people cut down trees and throw rubbish on the grass. Will our parks stay green? They will not, if this goes on. Next spring, our school is going to plant a hundred young trees. We are going to keep our parks clean too. If we all care for nature, the earth will stay green and full of life.', '绿色就是生命(一般现在时)', 106, 1, '[{"q": "What does a big tree give us on a hot day?", "answer": "B", "options": ["Warm air.", "Cool shade.", "Sweet fruit.", "Bright light."], "explanation": "''a big tree gives us cool shade''。"}, {"q": "What do some people do that is bad for the world?", "answer": "D", "options": ["Plant more trees.", "Keep parks clean.", "Water the plants.", "Cut down trees and throw rubbish."], "explanation": "''some people cut down trees and throw rubbish on the grass''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["Why green plants are important and how to protect them.", "How to build a bird''s home.", "Why trees are tall.", "Where the park is."], "explanation": "全文讲绿色即生命(现在时)。"}]'::jsonb, '[{"word": "nature", "cn": "大自然"}, {"word": "breathe", "cn": "呼吸"}, {"word": "shade", "cn": "树荫"}, {"word": "rubbish", "cn": "垃圾"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'The ants'' secret', 'I am doing a project about ants this week. At first, ants look boring to me. But now I am changing my mind. I am sitting by the garden with my notebook. A line of ants is moving across the path. They are carrying tiny pieces of food. The food is very big, but they are not giving up. Look! One ant is falling into a small hole. Two other ants are helping it. They are working together like good friends. Now it is starting to rain. The ants are running back to their home under the old tree. They are not pushing each other. They are moving in a neat line. Near the wall, some ants are building a new road with tiny stones. One big ant is cleaning its legs in the sun. They are never fighting, and they are never resting. I am reading a book about ants tonight. Ants are talking to each other with smells — that is what the book tells us. Some ants are even growing their own food! I am learning so much. Ants are small, but they are amazing. I am really glad about this project.', '奇妙的动物朋友', 194, 0, '[{"q": "What are the ants carrying?", "answer": "A", "options": ["Tiny pieces of food.", "Small stones.", "Green leaves.", "Drops of water."], "explanation": "原文 \"They are carrying tiny pieces of food.\""}, {"q": "What do two ants do when one falls into a hole?", "answer": "B", "options": ["They run away.", "They help it.", "They push it.", "They eat the food."], "explanation": "原文 \"Two other ants are helping it.\""}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Ants like rainy days.", "Gardens are full of insects.", "Ants are small but amazing.", "The writer enjoys reading books."], "explanation": "全文由\"boring\"到\"amazing\",说明蚂蚁虽小却了不起。"}, {"q": "How does the writer''s opinion of ants change?", "answer": "D", "options": ["From amazing to boring.", "It does not change.", "From scary to boring.", "From boring to amazing."], "explanation": "\"At first... boring. But now I am changing my mind... they are amazing.\" 可推断。"}, {"q": "\"They are moving in a neat line\" — \"neat\" means ____.", "answer": "A", "options": ["tidy and well-ordered", "broken and messy", "fast and wild", "slow and tired"], "explanation": "neat = 整齐的。"}]'::jsonb, '[{"word": "project", "cn": "项目,课题"}, {"word": "neat", "cn": "整齐的"}, {"word": "smell", "cn": "气味"}, {"word": "amazing", "cn": "了不起的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'The busy ants', 'Ants are very small, but they are amazing animals. They live together in big groups called colonies. Every ant has a job to do. Some ants look for food. When they find it, they carry it back home. Look! Some ants are running and carrying seeds. An ant is very strong. It can carry a very heavy piece of food. Other ants take care of the babies or clean the home. They all work together, and no ant is lazy. Ants talk to each other in a special way, with smells. When one ant finds food, it leaves a smell on the ground, so the others can follow. From ants, we learn an important lesson: team work makes hard things easy.', '忙碌的蚂蚁(一般现在时·科普)', 121, 1, '[{"q": "How do ants talk to each other?", "answer": "D", "options": ["With sounds.", "With colours.", "With songs.", "With smells."], "explanation": "''Ants talk to each other in a special way, with smells''。"}, {"q": "What lesson do we learn from ants?", "answer": "C", "options": ["Small things are weak.", "It is good to be lazy.", "Team work makes hard things easy.", "Food is important."], "explanation": "''team work makes hard things easy''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to find food.", "How busy ants live and work together as a team.", "Why ants are small.", "Where ants sleep."], "explanation": "全文讲蚂蚁团队(现在时·科普)。"}]'::jsonb, '[{"word": "colonies", "cn": "群体"}, {"word": "carry", "cn": "搬运"}, {"word": "lazy", "cn": "懒惰的"}, {"word": "smells", "cn": "气味"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'Animals are our friends', 'Animals share our world, and they are our good friends. Some animals help people every day. Dogs keep our homes safe. Cats catch small mice. That cat is not sleeping. It is watching the birds. On farms, cows give us milk, and bees make sweet honey. In the wild, every animal has its place. Birds eat bad insects, so trees can grow well. Even small animals are important for nature. But some animals are now in danger, because people cut down forests and dirty the water. We must always care for animals. We can protect their homes and keep the water clean. When we take care of animals, we take care of our world. A world with many animals is a happy and healthy world.', '动物是我们的朋友(一般现在时)', 125, 1, '[{"q": "What do birds eat that helps trees grow?", "answer": "A", "options": ["Bad insects.", "Sweet honey.", "Green leaves.", "Small fish."], "explanation": "''Birds eat bad insects, so trees can grow well''。"}, {"q": "Why are some animals now in danger?", "answer": "B", "options": ["Because they are too small.", "Because people cut down forests and dirty the water.", "Because they eat too much.", "Because they are lazy."], "explanation": "''people cut down forests and dirty the water''。"}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["How animals help us and why we should protect them.", "How to keep a dog.", "Why cats catch mice.", "Where bees live."], "explanation": "全文讲动物是朋友(现在时)。"}]'::jsonb, '[{"word": "mice", "cn": "老鼠(mouse的复数)"}, {"word": "honey", "cn": "蜂蜜"}, {"word": "insects", "cn": "昆虫"}, {"word": "danger", "cn": "危险"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'Birds in my garden', 'Every morning, birds come to my garden, and I love to watch them. There is a big tree near my window. Many small birds live in it. Early in the day, they sing sweet songs. Their music wakes me up every morning. I often put some bread and water on the ground for them. The birds are not afraid of me now. Some of them are brown, and some are grey with bright eyes. They fly fast and jump from branch to branch. In spring, they build small homes in the tree. Are they making a new home? One is singing now. Watching the birds makes me feel calm and happy. They remind me that nature is full of little wonders.', '我花园里的鸟(一般现在时)', 121, 1, '[{"q": "What does the writer put on the ground for the birds?", "answer": "C", "options": ["Rice and milk.", "Fruit and seeds.", "Bread and water.", "Nothing."], "explanation": "''I often put some bread and water on the ground for them''。"}, {"q": "What do the birds do in spring?", "answer": "D", "options": ["Fly away for good.", "Stop singing.", "Sleep all day.", "Build small homes in the tree."], "explanation": "''In spring, they build small homes in the tree''。"}, {"q": "What is the passage mainly about?", "answer": "B", "options": ["How to build a house.", "The birds that visit the writer''s garden every day.", "Why bread is white.", "Where the tree grows."], "explanation": "全文讲花园里的鸟(现在时)。"}]'::jsonb, '[{"word": "branch", "cn": "树枝"}, {"word": "afraid", "cn": "害怕的"}, {"word": "build", "cn": "建造"}, {"word": "wonders", "cn": "奇妙的事物"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'Little animals, big lessons', 'Small animals can teach us big lessons. Look at the ant. It is tiny, but it works hard and never gives up. It teaches us to keep trying. Look at the bee. It flies from flower to flower and makes sweet honey. Look! One bee is flying and taking honey home. It teaches us that hard work brings a sweet result. Birds fly high in the sky. They teach us to be free and brave. Even a slow little turtle has a lesson: ''Slow and steady wins the race.'' Animals do not use words, but they show us how to live. When we watch them with care, we learn about our own lives. Nature is a wise teacher, and its lessons are all around us, free for everyone.', '小动物,大道理(一般现在时)', 128, 1, '[{"q": "What does the bee teach us?", "answer": "C", "options": ["To fly high.", "To be slow.", "That hard work brings a sweet result.", "To give up."], "explanation": "''It teaches us that hard work brings a sweet result''。"}, {"q": "What lesson does the slow turtle give?", "answer": "A", "options": ["''Slow and steady wins the race.''", "Fly high and free.", "Work like an ant.", "Make sweet honey."], "explanation": "''Slow and steady wins the race''。"}, {"q": "What is the passage mainly about?", "answer": "D", "options": ["How to keep a turtle.", "Why bees make honey.", "Where birds fly.", "How small animals teach us big lessons about life."], "explanation": "全文讲小动物的大道理(现在时)。"}]'::jsonb, '[{"word": "tiny", "cn": "微小的"}, {"word": "honey", "cn": "蜂蜜"}, {"word": "turtle", "cn": "乌龟"}, {"word": "steady", "cn": "稳定的"}]'::jsonb);
