-- 外研社七上 wy7A 阅读合并灌库(junior_reading)· publisher=junior_fltrp · volume=wy7A · grade=7
-- 35篇 = 7精读(difficulty=0·5题)+ 28泛读(difficulty=1·3题·每单元4篇·全一般现在时)。原文全改写/原创。
-- 幂等:按(publisher,volume)先删后插。id 不预生成。★合并版:精读+泛读同一DELETE,勿再单独跑旧精读版★
BEGIN;

DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A';

-- Starter 精读
-- U1 精读
-- U2 精读
-- U3 精读
-- U4 精读
-- U5 精读
-- U6 精读

-- 断言
DO $$
DECLARE tot int; q5 int; q3 int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A';
  IF tot<>35 THEN RAISE EXCEPTION 'total=% 期望35', tot; END IF;
  SELECT count(*) INTO q5 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A' AND difficulty=0 AND jsonb_array_length(questions)=5;
  IF q5<>7 THEN RAISE EXCEPTION '精读(diff0/5题)=% 期望7', q5; END IF;
  SELECT count(*) INTO q3 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A' AND difficulty=1 AND jsonb_array_length(questions)=3;
  IF q3<>28 THEN RAISE EXCEPTION '泛读(diff1/3题)=% 期望28', q3; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A' GROUP BY unit HAVING count(*)<>5) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠5篇(1精读+4泛读)的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy7A 阅读 % 篇(精读7+泛读28)· 7单元各5', tot;
END $$;

COMMIT;

SELECT unit, count(*) 篇, min(jsonb_array_length(questions))||'-'||max(jsonb_array_length(questions)) 题数范围 FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A' GROUP BY unit ORDER BY unit;